//Возвращает SVG-разметку логотипа; элементы получают классы блока $block: __image, __mark, __word
function logo_svg(string $block): string
{
    $mark = '';
    foreach (LOGO_MARK as $path) {
        $mark .= '<path class="' . $block . '__mark" fill-rule="evenodd" d="' . $path . '"/>';
    }
    return '<svg class="' . $block . '__image" viewBox="0 0 1014 419" role="img" aria-label="Лекало">'
        . $mark . '<path class="' . $block . '__word" d="' . LOGO_WORD . '"/></svg>';
}
